    /**
     * Handles loading a Report using a UUID
     * @param		UUID uuid 
     * @return		Report
     */    
    @GetMapping("/load")
    public Report load( @RequestParam(required=true) UUID uuid ) {    	
    	Report entity = null;

    	try {  
    		entity = service.getReport( new ReportFetchOneSummary( uuid ) );   
        }
        catch( Throwable exc ) {
            LOGGER.log( Level.WARNING, "failed to load Report using Id " + uuid );
            return null;
        }

        return entity;
    }

