    @GetMapping("/")
    public List<Report> loadAll() {                
    	List<Report> reportList = null;
        
    	try {
            // load the Report
            reportList = service.getAllReport();
            
            if ( reportList != null )
                LOGGER.log( Level.INFO,  "successfully loaded all Reports" );
        }
        catch( Throwable exc ) {
            LOGGER.log( Level.WARNING,  "failed to load all Reports ", exc );
        	return null;
        }

        return reportList;
                            
    }

